mapper.insert:
INSERT /*LGVATT00023.insertVendorInfomation*/ INTO TB_VENDOR_MASTER
( vendor_id		
 ,vendor_code						
 ,vendor_name 						
 ,remark	
 ,effective_start_date
 ,effective_end_date					
 ,creation_user_id 					/* 사용자ID */
 ,creation_date 					/* 등록일자 */
 ,last_update_user_id 				/* 최종수정자ID */
 ,last_update_date 					/* 수정일자 */
) values
( SQ_TB_VENDOR_MASTER.NEXTVAL
 ,#{vendorCode}
 ,#{vendorName}
 ,#{remark}
 ,to_date(#{effectiveStartDate}, 'DD/MM/YYYY')
 ,to_date(#{effectiveEndDate}, 'DD/MM/YYYY')
 ,#{applicationUserId}
 ,trunc(sysdate)
 ,#{applicationUserId}
 ,trunc(sysdate)
)

mapper.update:
UPDATE /*LGVATT00023.updateVendorInfomation*/
       TB_VENDOR_MASTER 
SET    vendor_code                     = #{vendorCode}
     , vendor_name                     = #{vendorName}
     , remark                          = #{remark}
     , effective_start_date            = to_date(#{effectiveStartDate}, 'DD/MM/YYYY')
     , effective_end_date              = to_date(#{effectiveEndDate}, 'DD/MM/YYYY')
     , last_update_user_id             = #{applicationUserId}            							/* 최종수정사용자아이디 */
     , last_update_date                = trunc(sysdate)                 							/* 최종수정일자 */
WHERE  vendor_id                     = #{vendorId}
